file.content:
# How the packaged browser app is served, and how it reaches the Python server.
#
# The whole app answers on one address. Anything whose path starts with `/api/`
# is handed to the Python server; everything else is a file of the built browser
# app. Because both halves answer on the same address, the browser never makes a
# request to a second address, and there is no permission header to configure,
# explain, or get wrong.
#
# This file is used only by the packaged image. While working on the code the
# build tool's own dev server does the same forwarding, configured in
# `frontend/vite.config.ts`.

server {
    listen 80;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    # The Python server. `backend` is the name Docker Compose gives the other
    # container; on the private network between the two containers that name
    # resolves to its address. There is deliberately no slash after `8000`:
    # with one, nginx would strip `/api/` from the path, and the server, whose
    # every route lives under `/api/`, would answer with "not found".
    location /api/ {
        proxy_pass http://backend:8000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Everything else is the browser app. If the path names a real file, serve
    # it. If it does not, serve the app's one page and let the app decide what
    # to show — that is what makes a link to a page inside the app work when it
    # is opened directly rather than clicked.
    location / {
        try_files $uri $uri/ /index.html;
    }
}

